// Function to extract sections from raw analysis text
function parseAnalysis(text) {
    const sections = {
        key_themes: [],
        emotional_tone: [],
        quotes: [],
        central_text: ""
    };

    const lines = text.split('\n');
    let currentSection = '';

    for (let line of lines) {
        line = line.trim();
        if (!line) continue;

        // Detect section headers
        if (line.startsWith('### 1. Key Themes')) {
            currentSection = 'key_themes';
            continue;
        }
        if (line.startsWith('### 2. Emotional Tone')) {
            currentSection = 'emotional_tone';
            continue;
        }
        if (line.startsWith('### 3. Quotes')) {
            currentSection = 'quotes';
            continue;
        }
        if (line.startsWith('### 4. Central Text')) {
            currentSection = 'central_text';
            continue;
        }

        // Add line to appropriate section
        if (currentSection === 'central_text') {
            sections.central_text += (sections.central_text ? '\n' : '') + line;
        } else if (currentSection && line.startsWith('*')) {
            sections[currentSection].push(line.replace(/^\*+\s*/, ''));
        } else if (currentSection) {
            sections[currentSection].push(line);
        }
    }

    return sections;
}

// Process all items from the previous node
return $input.all().map(item => {
    const rawText = item.json.content.parts[0].text;
    const structured = parseAnalysis(rawText);

    return { json: structured };
});

